  A32: h => { h.node('edit-menu').identifier = 'expected-menu'; },
  A33: h => { h.node('control').identifier = 'delivered-control'; },
  A34: h => { h.on('admit', x => { x.snapshot.nodes.reverse(); }, 2); },
  A35: h => { h.snapshot.domains.options.enumeration = 'complete'; },
  A36: h => { h.node('coast').help = 'Loaded option'; },
  A37: h => { h.node('control').help = 'Selection only'; },
