  A39: h => { h.node('control').value = 'Coast'; h.snapshot.selection = { control: 'control', label: 'Coast', source: 'title', complete: true }; h.happySends = 0; },
  A40: h => { h.node('control').help = 'Declared value display'; },
  A41: h => { h.node('coast').help = 'Local value only'; },
  A42: h => menuLabel(h, 'Local lookup', 2),
